<script setup lang="ts">
import { ref } from 'vue'; import { useAuthStore } from '../stores/auth'; import { authApi, ApiError } from '../services/api'; import AppAlert from './AppAlert.vue'
const oldPassword=ref(''); const newPassword=ref(''); const confirm=ref(''); const loading=ref(false); const error=ref(''); const success=ref(''); const form=ref(); const auth=useAuthStore()
async function submit(){const result=await form.value.validate(); if(!result.valid || newPassword.value !== confirm.value){if(newPassword.value!==confirm.value) error.value='Las contraseñas no coinciden.';return}; loading.value=true;error.value='';try{await authApi.changePassword({current_password:oldPassword.value,new_password:newPassword.value},auth.token);success.value='Contraseña actualizada correctamente.';oldPassword.value='';newPassword.value='';confirm.value=''}catch(e){error.value=e instanceof ApiError?e.message:'No fue posible cambiar la contraseña.'}finally{loading.value=false}}
</script>
<template><v-form ref="form" @submit.prevent="submit"><AppAlert v-if="error" :message="error"/><v-alert v-if="success" type="success" variant="tonal" class="mb-4">{{success}}</v-alert><v-text-field v-model="oldPassword" type="password" label="Contraseña actual" :rules="[v=>!!v||'Campo requerido']"/><v-text-field v-model="newPassword" type="password" label="Nueva contraseña" :rules="[v=>/(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{10,}/.test(v)||'Usa 10+ caracteres, mayúscula, minúscula y número']"/><v-text-field v-model="confirm" type="password" label="Confirmar nueva contraseña" :rules="[v=>v===newPassword||'Las contraseñas no coinciden']"/><v-btn type="submit" color="primary" :loading="loading">Actualizar contraseña</v-btn></v-form></template>

